link:8430,
text:['"[{\"start\":0,\"editorState\":{\"blocks\":[{\"key\":\"6h9vj\",\"text\":\"Which dramatic literary devices were represented in the previous video clip? 1. Monologue and dialogue. 2. Soliloquy and dialogue. 3. Monologue and soliloquy. Or 4. All three literary devices. Hit submit when you are done.\",\"type\":\"unstyled\",\"depth\":0,\"inlineStyleRanges\":[{\"offset\":0,\"length\":222,\"style\":\"textShadowEnable:false\"},{\"offset\":0,\"length\":222,\"style\":\"hlnk:\"},{\"offset\":0,\"length\":222,\"style\":\"textShadowBlur:8px\"},{\"offset\":0,\"length\":222,\"style\":\"desktop-fontSize:24\"},{\"offset\":0,\"length\":222,\"style\":\"hlnke:true\"},{\"offset\":0,\"length\":222,\"style\":\"WebkitTextStrokeWidth:1px\"},{\"offset\":0,\"length\":222,\"style\":\"hlnkt:wp\"},{\"offset\":0,\"length\":222,\"style\":\"fontStyle:normal\"},{\"offset\":0,\"length\":222,\"style\":\"fontFamily:Raleway\"},{\"offset\":0,\"length\":222,\"style\":\"defaultTextStrokeWidth:1px\"},{\"offset\":0,\"length\":222,\"style\":\"mobile-fontSize:24\"},{\"offset\":0,\"length\":222,\"style\":\"WebkitTextStrokeColor:#F1EEE6\"},{\"offset\":0,\"length\":222,\"style\":\"fontWeight:400\"},{\"offset\":0,\"length\":222,\"style\":\"textOutlineEnable:false\"},{\"offset\":0,\"length\":222,\"style\":\"opacity:1\"},{\"offset\":0,\"length\":222,\"style\":\"defaultTextStrokeColor:#F1EEE6\"},{\"offset\":0,\"length\":222,\"style\":\"defaultTextShadow:none\"},{\"offset\":0,\"length\":222,\"style\":\"backgroundColor:unset\"},{\"offset\":0,\"length\":222,\"style\":\"tablet-fontSize:24\"},{\"offset\":0,\"length\":222,\"style\":\"textShadow:none\"},{\"offset\":0,\"length\":222,\"style\":\"textShadowX:0px\"},{\"offset\":0,\"length\":222,\"style\":\"fontStretch:normal\"},{\"offset\":0,\"length\":222,\"style\":\"fontType:regular\"},{\"offset\":0,\"length\":222,\"style\":\"color:#ffffff\"},{\"offset\":0,\"length\":222,\"style\":\"defaultBackgroundColor:#E8D01B\"},{\"offset\":0,\"length\":222,\"style\":\"textShadowY:4px\"},{\"offset\":0,\"length\":222,\"style\":\"textShadowColor:#F1EEE61F\"},{\"offset\":0,\"length\":222,\"style\":\"lineHeight:135%\"},{\"offset\":0,\"length\":222,\"style\":\"letterSpacing:0%\"},{\"offset\":0,\"length\":222,\"style\":\"textHighlightEnable:false\"},{\"offset\":0,\"length\":222,\"style\":\"textTransform:none\"},{\"offset\":0,\"length\":222,\"style\":\"textShadowOpacity:none\"},{\"offset\":0,\"length\":222,\"style\":\"overridden:true\"},{\"offset\":0,\"length\":222,\"style\":\"textDecoration:none\"},{\"offset\":0,\"length\":222,\"style\":\"borderBottomStyle:none\"}],\"entityRanges\":[],\"data\":{\"listDepth\":\"0\",\"listColor\":\"#666666\",\"listIndent\":\"100%\",\"verticalAlign\":\"middle\",\"overridden\":\"true\",\"marginLeft\":\"0px\",\"listType\":\"S_Bullets08\",\"textAlign\":\"center\",\"marginBottom\":\"0%\",\"presetId\":\"text-closedcaptions\",\"listSize\":\"100%\"}}],\"entityMap\":{}},\"CCPosition\":\"BOTTOM\",\"text\":\"Type caption here\",\"duration\":1.4,\"end\":1.4,\"id\":\"caption__7649__2\",\"dirtyReasons\":[],\"speechAgentV1\":{\"name\":\"Nathaniel C. - Natural Conversations\",\"voiceId\":{\"uid\":\"lnIpQcZuikKim3oNdYlP\",\"modelId\":\"1\"},\"source\":\"AIVoices\"}}]"']
